[tool error]
{
  "ok": false,
  "name": "create_alignment",
  "error": {
    "type": "invalid_params",
    "message": "'name' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1
        },
        "pis": {
          "type": "array",
          "items": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "minItems": 2,
            "maxItems": 3,
            "description": "[x, y] or [x, y, radius]"
          },
          "minItems": 2
        },
        "elements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "kind": {
                "enum": [
                  "tangent",
                  "curve"
                ]
              },
              "start": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "end": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "pc": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "pt": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "center": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "radius": {
                "type": "number",
                "exclusiveMinimum": 0
              },
              "direction": {
                "enum": [
                  "L",
                  "R"
                ]
              }
            },
            "required": [
              "kind"
            ],
            "additionalProperties": false
          },
          "minItems": 1
        },
        "start": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "BEGIN, where legs start: [x, y] = [easting, northing]"
        },
        "legs": {
          "type": "array",
          "items": {
            "type": [
              "object",
              "string"
            ],
            "description": "one tangent, from one PI to the next: a direction (exactly one of bearing, azimuth, deflection, angle_right) and the distance to the next PI; radius is the curve at the PI where this leg starts (a leg after the first). Or as text: \"S 80°00'00\\\" E 800\", \"40 L 700 R=500\"",
            "properties": {
              "bearing": {
                "type": "string",
                "description": "quadrant bearing: N 45°30'15\" E, S45-30-15W, N45E"
              },
              "azimuth": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "degrees clockwise from north, 0-360"
              },
              "deflection": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "the angle the alignment turns at the PI where this leg starts: '40 L', '25°00'00\" RT', or a number with right positive; or its size with turn"
              },
              "turn": {
                "type": "string",
                "enum": [
                  "left",
                  "right",
                  "L",
                  "R"
                ],
                "description": "which way a deflection turns"
              },
              "angle_right": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "angle clockwise from the backsight"
              },
              "distance": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "feet from this leg's PI to the next PI"
              },
              "radius": {
                "type": "number",
                "minimum": 0,
                "description": "the curve at the PI where this leg starts (0 or omitted: none, which needs angle_points)"
              }
            },
            "additionalProperties": false
          },
          "minItems": 1,
          "description": "the layout as bearings and distances, PI to PI from start -- as a report describes it: 'S 80° E 800 ft to PI-2, where it deflects 40° left on a 500 ft curve; then 700 ft...' is [{bearing: 'S 80 E', distance: 800}, {deflection: '40 L', radius: 500, distance: 700}, ...]"
        },
        "begin_station": {
          "type": [
            "number",
            "string"
          ],
          "description": "display station: feet (1600) or '16+00.00'"
        },
        "equations": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "back": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "display station: feet (1600) or '16+00.00'"
              },
              "ahead": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "display station: feet (1600) or '16+00.00'"
              },
              "raw_station": {
                "type": "number"
              }
            },
            "required": [
              "back",
              "ahead"
            ],
            "additionalProperties": false
          }
        },
        "description": {
          "type": "string"
        },
        "angle_points": {
          "type": "boolean",
          "description": "allow interior PIs of radius 0: angle points, where the tangents meet with no curve -- a layout whose curves come later (default false: a missing radius is refused)"
        }
      },
      "required": [
        "name"
      ],
      "additionalProperties": false
    },
    "example": {
      "name": "ALIGN-1",
      "begin_station": "10+00",
      "pis": [
        [
          1000,
          1000
        ],
        [
          1814.359354,
          1000,
          800
        ],
        [
          2433.012702,
          1357.179677
        ]
      ]
    }
  },
  "warnings": []
}
